// #105 Phase 3 Task 5 — publish-time script embedding (tests).
//
// Two layers:
// 1. CHUNKER PARITY — lib/brain-embed.mjs chunkScriptText must produce
//   byte-identical output to services/ai/brain/chunker.py chunk_text (the
//   SAME chunker must run on the publish side and the backfill side, or
//   identical scripts get different content fingerprints). The expected
//   values below were GENERATED by the real Python chunker (word-index
//   ranges over a deterministic w0..wN corpus, plus one verbatim
//   messy-whitespace case). If the Python chunker ever changes, these
//   fixtures break — that is the point; update both sides together.
// 2. EMBED BEHAVIOR — env-gated, ghost-excluded (only uploaded scripts with
//   text), reachability-probed, one POST per script, non-fatal on every
//   failure mode, short deadline armed.
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import { chunkScriptText, embedPublishedScripts } from '../lib/brain-embed.mjs';

// ---- helpers --------------------------------------------------------------

const words = (n) => Array.from({ length: n }, (_, i) => `w${i}`);
const wordsText = (n) => words(n).join(' ');
// Expected chunk text "w<from> .. w<to>" reconstructed INDEPENDENTLY of the
// implementation (the Python fixture is the word-index range, not the text).
const rangeText = (from, to) => wordsText(to + 1).split(' ').slice(from, to + 1).join(' ');

// Generated by: brain.chunker.chunk_text on ' '.join(f'w{i}' for i in range(N))
// [chunk_kind, fromWordIndex, toWordIndexInclusive]
const PY_FIXTURES = [
  ['doc 480 words -> 4 scene windows + pooled', 'doc', 480, [
    ['scene', 0, 149], ['scene', 130, 279], ['scene', 260, 409], ['scene', 390, 479], ['pooled', 0, 479],
  ]],
  ['doc exactly 151 words -> window boundary (scene 150 + tail 21 + pooled)', 'doc', 151, [
    ['scene', 0, 149], ['scene', 130, 150], ['pooled', 0, 150],
  ]],
  ['doc exactly 150 words -> no window (strict >), pooled only', 'doc', 150, [
    ['pooled', 0, 149],
  ]],
  ['doc short 100 words -> pooled only', 'doc', 100, [
    ['pooled', 0, 99],
  ]],
  ['shorts 130 words -> hook 60 + points 70 + pooled', 'shorts', 130, [
    ['hook', 0, 59], ['points', 60, 129], ['pooled', 0, 129],
  ]],
  ['shorts exactly 61 words -> hook + 1-word points + pooled', 'shorts', 61, [
    ['hook', 0, 59], ['points', 60, 60], ['pooled', 0, 60],
  ]],
  ['shorts exactly 60 words -> no hook split, pooled only', 'shorts', 60, [
    ['pooled', 0, 59],
  ]],
  ['empty text -> no chunks (nothing to embed)', 'doc', 0, []],
  ['whitespace-only text -> no chunks', 'shorts', 0, []],
];

// Verbatim Python output for a messy-whitespace text (pooled keeps the RAW
// original text — hook/points would be normalized, this input is under the
// 60-word hook threshold so only pooled fires):
//   chunk_text('shorts', '  alpha  beta\ngamma \t delta   epsilon\n\n zeta   eta  ')
//   -> [{"chunk_kind": "pooled", "text": <the input, untouched>}]
const MESSY = '  alpha  beta\ngamma \t delta   epsilon\n\n zeta   eta  ';

// ---- env helper -----------------------------------------------------------

function withEnv(overrides, fn) {
  const saved = {};
  for (const k of Object.keys(overrides)) saved[k] = process.env[k];
  for (const [k, v] of Object.entries(overrides)) {
    if (v === undefined) delete process.env[k]; else process.env[k] = v;
  }
  return Promise.resolve()
    .then(fn)
    .finally(() => {
      for (const [k, v] of Object.entries(saved)) {
        if (v === undefined) delete process.env[k]; else process.env[k] = v;
      }
    });
}

// ===========================================================================
// 1. Chunker parity with services/ai/brain/chunker.py
// ===========================================================================

describe('#105 chunker parity with the Python brain chunker', () => {
  for (const [name, kind, n, expected] of PY_FIXTURES) {
    test(name, () => {
      const input = name.startsWith('whitespace') ? '   ' : wordsText(n); // n=0 -> ''
      const got = chunkScriptText(kind, input);
      assert.equal(got.length, expected.length, `chunk count: ${JSON.stringify(got.map(c => c.chunk_kind))}`);
      expected.forEach(([chunkKind, from, to], i) => {
        assert.equal(got[i].chunk_kind, chunkKind, `chunk ${i} kind`);
        assert.equal(got[i].text, rangeText(from, to), `chunk ${i} text must be byte-identical to the Python chunker`);
      });
    });
  }

  test('pooled chunk keeps the RAW text (no whitespace normalization) — matches Python', () => {
    const got = chunkScriptText('shorts', MESSY);
    assert.equal(got.length, 1);
    assert.equal(got[0].chunk_kind, 'pooled');
    assert.equal(got[0].text, MESSY);
  });

  test('unknown kind throws (mirror of the Python ValueError)', () => {
    assert.throws(() => chunkScriptText('research', 'irrelevant — publish never sends this'), /unknown chunk kind/);
  });
});

// ===========================================================================
// 2. embedPublishedScripts behavior
// ===========================================================================

function stubFetch(handlers) {
  const calls = [];
  const fetchImpl = async (url, opts = {}) => {
    calls.push({ url, opts, body: opts.body ? JSON.parse(opts.body) : null });
    const h = handlers.find(([match]) => url.includes(match));
    if (!h) throw new Error(`stub: no handler for ${url}`);
    const [, respond] = h;
    return respond(calls[calls.length - 1]);
  };
  return { calls, fetchImpl };
}

describe('#105 publish-time embed — gating and ghost exclusion', () => {
  test('BRAIN_EMBED_ENABLED off (default) -> skipped, zero requests', async () => {
    const { calls, fetchImpl } = stubFetch([]);
    const out = await withEnv({ BRAIN_EMBED_ENABLED: undefined }, () =>
      embedPublishedScripts({ slug: 'quotequarry', kind: 'shorts', entries: [{ videoId: 'vid1', text: 'x' }], fetchImpl }));
    assert.equal(out.status, 'skipped');
    assert.equal(out.reason, 'disabled');
    assert.equal(calls.length, 0, 'no HTTP at all when the flag is off');
  });

  test('flag on, but entries without videoId (ghost scripts) or text -> dropped, only real uploads POSTed', async () => {
    const { calls, fetchImpl } = stubFetch([
      ['/health', () => ({ ok: true, status: 200 })],
      ['/embed', () => ({ ok: true, status: 200, json: async () => ({ inserted: 1, updated: 0 }) })],
    ]);
    const out = await withEnv({ BRAIN_EMBED_ENABLED: '1' }, () =>
      embedPublishedScripts({
        slug: 'quotequarry', kind: 'shorts',
        entries: [
          { videoId: null, text: 'gate-rejected ghost' },   // never uploaded (AC-P3-2)
          { videoId: 'vid2', text: null },                  // uploaded pre-capture (old state)
          { videoId: 'vid3', text: '   ' },                 // whitespace-only -> chunker yields []
          { videoId: 'vid4', text: 'a real uploaded script '.repeat(20) },
        ],
        fetchImpl,
      }));
    const posts = calls.filter((c) => c.url.includes('/embed'));
    assert.equal(posts.length, 1, 'exactly one POST — only the uploaded script with text');
    assert.equal(posts[0].body.video_id, 'vid4');
    assert.equal(out.status, 'ok');
    assert.equal(out.embedded, 1);
    assert.equal(out.dropped, 3, 'the three ineligible entries are counted as dropped');
  });

  test('sidecar unreachable -> skipped, no throw, no POST', async () => {
    const { calls, fetchImpl } = stubFetch([]); // every request throws (connection refused analogue)
    const out = await withEnv({ BRAIN_EMBED_ENABLED: '1' }, () =>
      embedPublishedScripts({ slug: 'q', kind: 'shorts', entries: [{ videoId: 'v', text: 't' }], fetchImpl }));
    assert.equal(out.status, 'skipped');
    assert.equal(out.reason, 'unreachable');
    assert.equal(calls.length, 1);
    assert.ok(!calls.some((c) => c.url.includes('/embed')), 'no /embed POST when /health fails');
  });

  test('/health non-200 -> skipped, no POST', async () => {
    const { calls, fetchImpl } = stubFetch([['/health', () => ({ ok: false, status: 503 })]]);
    const out = await withEnv({ BRAIN_EMBED_ENABLED: '1' }, () =>
      embedPublishedScripts({ slug: 'q', kind: 'doc', entries: [{ videoId: 'v', text: 't' }], fetchImpl }));
    assert.equal(out.status, 'skipped');
    assert.equal(out.reason, 'unreachable');
    assert.equal(calls.filter((c) => c.url.includes('/embed')).length, 0);
  });
});

describe('#105 publish-time embed — happy path (pinned request shape)', () => {
  test('one POST per uploaded script with the pinned /embed body; BRAIN_PORT honored', async () => {
    const { calls, fetchImpl } = stubFetch([
      ['/health', () => ({ ok: true, status: 200 })],
      // vidA: 3 chunks all new; vidB: 1 chunk seen before (update in place)
      ['/embed', ({ body }) => ({ ok: true, status: 200, json: async () => (
        body.video_id === 'vidA' ? { inserted: 3, updated: 0 } : { inserted: 0, updated: 1 }
      ) })],
    ]);
    const scriptText = wordsText(130); // shorts-sized -> hook + points + pooled
    const out = await withEnv({ BRAIN_EMBED_ENABLED: '1', BRAIN_PORT: '8971', GITHUB_RUN_ID: undefined }, () =>
      embedPublishedScripts({
        slug: 'quotequarry', kind: 'shorts', jobId: 'job-fixed',
        entries: [
          { videoId: 'vidA', text: scriptText },
          { videoId: 'vidB', text: 'short script pooled only text words here padding padding' },
        ],
        fetchImpl,
      }));
    assert.equal(out.status, 'ok');
    assert.equal(out.embedded, 2);
    assert.equal(out.inserted, 3);
    assert.equal(out.updated, 1);

    const posts = calls.filter((c) => c.url.includes('/embed'));
    assert.equal(posts.length, 2, 'one POST per script');
    for (const p of posts) {
      assert.ok(p.url.startsWith('http://localhost:8971/embed'), `BRAIN_PORT override: ${p.url}`);
      assert.equal(p.opts.method, 'POST');
      assert.equal(p.opts.headers['Content-Type'], 'application/json');
      assert.ok(p.opts.signal instanceof AbortSignal, 'a deadline must be armed');
      assert.equal(p.body.channel, 'quotequarry');
      assert.equal(p.body.kind, 'shorts');
      assert.equal(p.body.job_id, 'job-fixed');
      assert.ok(p.body.video_id);
      assert.ok(Array.isArray(p.body.chunks) && p.body.chunks.length > 0);
      for (const c of p.body.chunks) {
        assert.ok(c.chunk_kind && typeof c.text === 'string');
      }
    }
    const big = posts.find((p) => p.body.video_id === 'vidA');
    assert.deepEqual(big.body.chunks.map((c) => c.chunk_kind), ['hook', 'points', 'pooled']);
    assert.equal(big.body.chunks[0].text, rangeText(0, 59));
    const small = posts.find((p) => p.body.video_id === 'vidB');
    assert.deepEqual(small.body.chunks.map((c) => c.chunk_kind), ['pooled']);
  });

  test('job_id defaults to <run|local>-<today> when not passed', async () => {
    const { calls, fetchImpl } = stubFetch([
      ['/health', () => ({ ok: true, status: 200 })],
      ['/embed', () => ({ ok: true, status: 200, json: async () => ({ inserted: 1, updated: 0 }) })],
    ]);
    await withEnv({ BRAIN_EMBED_ENABLED: '1', GITHUB_RUN_ID: '424242' }, () =>
      embedPublishedScripts({ slug: 'q', kind: 'doc', entries: [{ videoId: 'v', text: 't' }], fetchImpl }));
    assert.equal(calls.find((c) => c.url.includes('/embed')).body.job_id, '424242-' + new Date().toISOString().slice(0, 10));
  });

  test('doc kind chunks scenes + pooled into the POST body', async () => {
    const { calls, fetchImpl } = stubFetch([
      ['/health', () => ({ ok: true, status: 200 })],
      ['/embed', () => ({ ok: true, status: 200, json: async () => ({ inserted: 0, updated: 0 }) })],
    ]);
    await withEnv({ BRAIN_EMBED_ENABLED: '1' }, () =>
      embedPublishedScripts({ slug: 'q', kind: 'doc', entries: [{ videoId: 'v', text: wordsText(480) }], fetchImpl }));
    const post = calls.find((c) => c.url.includes('/embed'));
    assert.deepEqual(post.body.chunks.map((c) => c.chunk_kind), ['scene', 'scene', 'scene', 'scene', 'pooled']);
  });
});

describe('#105 publish-time embed — non-fatal on every failure', () => {
  test('POST 500 -> logged, counted failed, remaining entries still attempted, no throw', async () => {
    const { calls, fetchImpl } = stubFetch([
      ['/health', () => ({ ok: true, status: 200 })],
      ['/embed', ({ body }) => (body.video_id === 'bad'
        ? { ok: false, status: 500 }
        : { ok: true, status: 200, json: async () => ({ inserted: 1, updated: 0 }) })],
    ]);
    const out = await withEnv({ BRAIN_EMBED_ENABLED: '1' }, () =>
      embedPublishedScripts({
        slug: 'q', kind: 'shorts',
        entries: [{ videoId: 'bad', text: 'x' }, { videoId: 'good', text: 'y' }],
        fetchImpl,
      }));
    assert.equal(out.status, 'partial');
    assert.equal(out.embedded, 1);
    assert.equal(out.failed, 1);
    assert.equal(calls.filter((c) => c.url.includes('/embed')).length, 2, 'failure must not stop the remaining scripts');
  });

  test('POST network error -> non-fatal', async () => {
    const fetchImpl = async (url) => {
      if (url.includes('/health')) return { ok: true, status: 200 };
      throw new Error('ECONNRESET');
    };
    const out = await withEnv({ BRAIN_EMBED_ENABLED: '1' }, () =>
      embedPublishedScripts({ slug: 'q', kind: 'shorts', entries: [{ videoId: 'v', text: 't' }], fetchImpl }));
    assert.equal(out.status, 'partial');
    assert.equal(out.failed, 1);
  });

  test('a stalled /embed response trips the deadline and the call still resolves (real server)', async () => {
    const srv = http.createServer((req, res) => {
      // health answers instantly; /embed accepts the request and stalls forever
      if (req.url === '/health') { res.writeHead(200); res.end('{}'); return; }
      res.writeHead(200); res.write('{'); // no res.end() — stalls past the deadline
    });
    await new Promise((r) => srv.listen(0, r));
    const port = srv.address().port;
    const started = Date.now();
    try {
      const out = await withEnv({ BRAIN_EMBED_ENABLED: '1', BRAIN_PORT: String(port), BRAIN_EMBED_TIMEOUT_MS: '300' }, () =>
        embedPublishedScripts({ slug: 'q', kind: 'shorts', entries: [{ videoId: 'v', text: 't' }] }));
      const elapsed = Date.now() - started;
      assert.ok(elapsed < 5000, `deadline must trip, took ${elapsed}ms`);
      assert.equal(out.status, 'partial');
      assert.equal(out.failed, 1, 'the stall counts as a failed (non-fatal) embed');
    } finally {
      srv.closeAllConnections?.();
      await new Promise((r) => srv.close(r));
    }
  });
});
